struct BinaryCacheStats {
    /// Programs successfully loaded from the persisted cache.
    uint64_t hits;
    /// Programs not in the cache (or load rejected) that fell back to full compile.
    uint64_t misses;
    /// Programs that, after compile, wrote a fresh binary back to the cache.
    uint64_t stores;
    /// Threads that blocked waiting for another thread's in-progress compile,
    /// then loaded that thread's freshly-written binary instead of recompiling.
    /// In multi-context RL setups this should approximate
    /// `worker_thread_count - 1` per shader after warmup.
    uint64_t coordinatedWaits;
  }

