struct RenderOverrides {
    /// Mesh shader override (defaults to shaders_["mesh"]).
    Shader* mesh = nullptr;
    /// Point cloud shader override (defaults to shaders_["pointcloud"]).
    Shader* pointcloud = nullptr;
    /// Picking shader override (defaults to shaders_["picking"]).
    Shader* picking = nullptr;
    /// Post-process shader override (defaults to shaders_["post"]).
    Shader* post = nullptr;
    /// Enable shadow passes.
    bool doShadows = true;
    /// Draw coordinate frames.
    bool drawCoordinateFrames = true;
    /// Draw point clouds that are marked detectable in external-camera captures.
    bool drawPointClouds = true;
    /// Draw custom visuals and instanced visuals that are marked detectable.
    bool drawVisualizationObjects = true;
    /// Draw viewer-only weather effects such as precipitation particles.
    bool drawWeatherEffects = true;
    /// Skip halfspace and heightmap ground objects in scene-color rendering.
    bool skipGroundObjects = false;
    /// Optional cubemap rendered as a viewer background before scene geometry.
    unsigned int environmentBackgroundMap = 0;
    /// Exposure applied to environmentBackgroundMap when rendered as background.
    float environmentBackgroundExposure = 1.0f;
    /// Apply external-camera postprocessing after rendering.
    bool postProcess = true;
    /// Allow quality preset MSAA for this external render. Sensor overloads force this off.
    bool allowViewerMsaa = true;
    /// Allow quality preset temporal AA for this external render. Sensor overloads force this off.
    bool allowTemporalAa = true;
    /// Allow quality preset lower-resolution viewer rendering followed by upscale.
    bool allowViewerUpscale = true;
    /// Use @ref fixedShadowCenter instead of the camera-derived directional
    /// shadow center, so offline multi-view captures share one shadow region.
    /// Uses one cascade; normal shadow dirty tracking remains active.
    bool fixedShadowCenterEnabled = false;
    /// World-space directional shadow center used when fixedShadowCenterEnabled is true.
    glm::vec3 fixedShadowCenter{0.f};
  }

struct SupersampledCapture {
    /// Output width in pixels (the input camera's render-target width).
    int width = 0;
    /// Output height in pixels (the input camera's render-target height).
    int height = 0;
    /// Supersampling factor actually used, clamped to [1, 4].
    int scale = 1;
    /// Box-downsampled RGBA8 pixels, top-left row order.
    std::vector<unsigned char> rgba;
  }

struct DebugPassCapture {
    /// Suggested PNG file name, e.g. `debug_02_normal.png`.
    std::string fileName;
    /// Short pass label, e.g. `normal`.
    std::string label;
    /// PBR debug output mode used for this pass (see setPbrDebugOutputMode()).
    int pbrDebugOutput = 0;
    /// Post-process debug mode used for this pass.
    PostProcessDebugMode postProcessDebugMode = PostProcessDebugMode::Final;
    /// Capture width in pixels.
    int width = 0;
    /// Capture height in pixels.
    int height = 0;
    /// RGBA8 pixels in top-left row order, ready for PNG writers.
    std::vector<unsigned char> rgba;
  }

struct RgbaLuminanceMetrics {
    /// Image width passed in.
    int width = 0;
    /// Image height passed in.
    int height = 0;
    /// Number of pixels analysed.
    size_t pixelCount = 0;
    /// Mean luminance.
    double averageLuminance = 0.0;
    /// 50th percentile luminance.
    double medianLuminance = 0.0;
    /// 95th percentile luminance.
    double p95Luminance = 0.0;
    /// 99th percentile luminance.
    double p99Luminance = 0.0;
    /// Minimum luminance.
    double minLuminance = 0.0;
    /// Maximum luminance.
    double maxLuminance = 0.0;
    /// Mean per-pixel saturation.
    double averageSaturation = 0.0;
    /// p95Luminance / medianLuminance (0 when the median is ~0).
    double contrastP95ToMedian = 0.0;
    /// Fraction of RGB channel values >= 250.
    double clippedChannelFraction = 0.0;
  }

struct ExposureRecommendation {
    /// False when the inputs were invalid (reason is `invalid_input`).
    bool valid = false;
    /// True when the recommended scale differs from 1 by more than 2 %.
    bool changed = false;
    /// Midtones are below 70 % of the target median.
    bool underexposed = false;
    /// Highlights exceed the p95 target or midtones exceed 135 % of the target median.
    bool overexposed = false;
    /// More than 1 % of channel values are clipped.
    bool clippingRisk = false;
    /// Exposure the metrics were captured with.
    double currentExposure = 1.0;
    /// Suggested exposure, clamped to [minExposure, maxExposure].
    double recommendedExposure = 1.0;
    /// recommendedExposure / currentExposure.
    double recommendedExposureScale = 1.0;
    /// Target median luminance used.
    double targetMedianLuminance = 0.45;
    /// Target 95th percentile luminance used.
    double targetP95Luminance = 0.90;
    /// Lower exposure bound used.
    double minExposure = 0.125;
    /// Upper exposure bound used.
    double maxExposure = 8.0;
    /// Machine-readable reason, e.g. `highlight_clipping`, `lift_midtones`, `within_target`.
    std::string reason;
  }

struct RgbaLuminanceHistogram {
    /// Image width passed in.
    int width = 0;
    /// Image height passed in.
    int height = 0;
    /// Number of pixels counted.
    size_t pixelCount = 0;
    /// Number of equal-width bins over luminance [0, 1].
    size_t binCount = 0;
    /// Index of the most populated bin.
    size_t peakBin = 0;
    /// Fraction of pixels in peakBin.
    double peakFraction = 0.0;
    /// Pixel count per bin.
    std::vector<size_t> bins;
  }

struct RgbaOutputTransform {
    /// Linear multiplier (negative values act as 0).
    double exposure = 1.0;
    /// Per-channel RGB multiplier.
    glm::vec3 whiteBalance = glm::vec3(1.0f);
    /// 0 = greyscale, 1 = unchanged, above 1 = more saturated.
    double saturation = 1.0;
    /// Output gamma; values <= 0 are treated as 1.
    double gamma = 1.0;
  }

struct RgbaCalibrationPatch {
    /// Patch name, copied to the result.
    std::string name;
    /// Left edge in pixels (top-left origin).
    int x = 0;
    /// Top edge in pixels (top-left origin).
    int y = 0;
    /// Width in pixels; clipped to the image.
    int width = 0;
    /// Height in pixels; clipped to the image.
    int height = 0;
    /// Expected display-space RGB in [0, 1].
    glm::vec3 targetRgb = glm::vec3(0.0f);
  }

struct RgbaCalibrationPatchResult {
    /// Patch name.
    std::string name;
    /// False when the patch does not overlap the image.
    bool valid = false;
    /// Number of pixels averaged.
    size_t sampleCount = 0;
    /// Mean measured display-space RGB in [0, 1].
    glm::vec3 measuredRgb = glm::vec3(0.0f);
    /// Target RGB, clamped to [0, 1].
    glm::vec3 targetRgb = glm::vec3(0.0f);
    /// Euclidean RGB distance between measured and target.
    double rgbError = 0.0;
    /// Largest absolute per-channel difference.
    double maxChannelError = 0.0;
    /// Absolute luminance difference.
    double luminanceError = 0.0;
    /// Absolute saturation difference.
    double saturationError = 0.0;
  }

struct RgbaCalibrationMetrics {
    /// Image width passed in.
    int width = 0;
    /// Image height passed in.
    int height = 0;
    /// Number of patches passed in.
    size_t patchCount = 0;
    /// Number of patches that overlapped the image.
    size_t validPatchCount = 0;
    /// Mean of RgbaCalibrationPatchResult::rgbError.
    double averageRgbError = 0.0;
    /// Root mean square of rgbError.
    double rmsRgbError = 0.0;
    /// Largest rgbError.
    double maxRgbError = 0.0;
    /// Mean luminance error.
    double averageLuminanceError = 0.0;
    /// Mean saturation error.
    double averageSaturationError = 0.0;
    /// One entry per input patch, in input order.
    std::vector<RgbaCalibrationPatchResult> patches;
  }

struct RgbaCalibrationRecommendation {
    /// False when no usable neutral or saturated reference patch exists.
    bool valid = false;
    /// True when the transform differs noticeably from identity.
    bool changed = false;
    /// Patches with target saturation below 0.08 (drive exposure and white balance).
    size_t neutralPatchCount = 0;
    /// Patches with target saturation above 0.15 (drive saturation).
    size_t saturatedPatchCount = 0;
    /// RgbaCalibrationMetrics::averageRgbError of the input.
    double averageRgbErrorBefore = 0.0;
    /// Suggested transform for transformRgbaForOutput(); gamma is always 1.
    RgbaOutputTransform outputTransform;
    /// Machine-readable reason, e.g. `calibration_output_transform`, `already_calibrated`.
    std::string reason;
  }

struct ReflectionProbeCaptureSettings {
    /// Cubemap face size in pixels, clamped to [16, 512].
    int resolution = 64;
    /// Draw custom visuals and instanced visuals that are marked detectable.
    bool drawVisualizationObjects = true;
    /// Draw coordinate frames into the probe.
    bool drawCoordinateFrames = false;
    /// Draw point clouds that are marked detectable.
    bool drawPointClouds = false;
    /// Render shadows while capturing.
    bool doShadows = false;
    /// Draw @ref environmentBackgroundMap behind the captured scene.
    bool includeEnvironmentBackground = false;
    /// Background cubemap used when includeEnvironmentBackground is true.
    unsigned int environmentBackgroundMap = 0;
