    float environmentBackgroundExposure = 1.0f;
  }

struct ReflectionProbeFilterSettings {
    /// Diffuse irradiance cubemap face size, clamped to [0, 128]; 0 skips the irradiance map.
    int irradianceResolution = 16;
    /// Cosine-hemisphere samples per irradiance texel; 0 skips the irradiance map.
    int irradianceSamples = 64;
    /// Prefiltered specular cubemap base face size, clamped to [0, 512]; 0 skips it.
    int prefilteredResolution = 64;
    /// Prefiltered mip levels (roughness steps), limited to the full mip chain; 0 skips it.
    int prefilteredMipLevels = 5;
    /// GGX samples per prefiltered texel; 0 skips the prefiltered map.
    int prefilteredSamples = 64;
    /// Split-sum BRDF LUT size (clamped to [16, 512] when used); 0 skips the LUT.
    int brdfLutSize = 128;
    /// GGX samples per BRDF LUT texel; 0 skips the LUT.
    int brdfLutSamples = 128;
