members.source:
class VisualMeshBuilder {
   public:
    /// @param renderer Renderer that add() creates the visual in (not owned).
    /// @param name Visual name (must be unique). @param meshFile Mesh file path.
    VisualMeshBuilder(RayraiWindow& renderer, std::string name, std::string meshFile)
        : renderer_(&renderer), name_(std::move(name)), meshFile_(std::move(meshFile)) {}
    /// Per-axis mesh scale (default 1). @param s Scale. @return *this.
    VisualMeshBuilder& scale(const glm::dvec3& s) { scale_ = s; return *this; }
    /// Per-axis mesh scale. @param x X scale. @param y Y scale. @param z Z scale. @return *this.
    VisualMeshBuilder& scale(double x, double y, double z) {
      scale_ = glm::dvec3{x, y, z};
      return *this;
    }
    /// RGBA color in [0, 1] (default white). @param c Color. @return *this.
    VisualMeshBuilder& color(const glm::vec4& c) { color_ = c; return *this; }
    /// World-space position. @param p Position in metres. @return *this.
    VisualMeshBuilder& position(const glm::vec3& p) { position_ = p; return *this; }
    /// World-space orientation. @param q Unit quaternion. @return *this.
    VisualMeshBuilder& orientation(const glm::quat& q) { orientation_ = q; return *this; }
    /// Disable back-face culling. @param enabled Flag. @return *this.
    VisualMeshBuilder& twoSided(bool enabled = true) { twoSided_ = enabled; return *this; }
    /// Sets Visuals::setDetectable(), which controls picking and visibility in
    /// sensor-style captures. @param enabled Flag. @return *this.
    VisualMeshBuilder& pickable(bool enabled = true) { pickable_ = enabled; return *this; }
    /// Whether the visual casts shadows. @param enabled Flag. @return *this.
    VisualMeshBuilder& castsShadows(bool enabled = true) { castsShadows_ = enabled; return *this; }
    /// Use the mesh file's own colors instead of color(). @param enabled Flag. @return *this.
    VisualMeshBuilder& useMeshColor(bool enabled) { useMeshColor_ = enabled; return *this; }
    /// Material override shared with the caller. @param m Material. @return *this.
    VisualMeshBuilder& material(std::shared_ptr<Material> m) {
      material_ = std::move(m);
      return *this;
    }
    /// Material override (copied). @param m Material. @return *this.
    VisualMeshBuilder& material(const Material& m) {
      material_ = std::make_shared<Material>(m);
      return *this;
    }
    /// Image-based lighting maps for the visual. @param env Environment. @return *this.
    VisualMeshBuilder& pbrEnvironment(const PbrEnvironment& env) { pbrEnv_ = env; return *this; }
    /** @brief Create the visual, apply the deferred state, return the shared_ptr.
     *  @return The new visual (the name must be unique, `RSFATAL` otherwise). */
    [[nodiscard]] std::shared_ptr<Visuals> add();

   private:
    RayraiWindow* renderer_;
    std::string name_;
    std::string meshFile_;
    glm::dvec3 scale_{1.0, 1.0, 1.0};
    glm::vec4 color_{1.0f, 1.0f, 1.0f, 1.0f};
    std::optional<glm::vec3> position_;
    std::optional<glm::quat> orientation_;
    std::optional<bool> twoSided_;
    std::optional<bool> pickable_;
    std::optional<bool> castsShadows_;
    std::optional<bool> useMeshColor_;
    std::shared_ptr<Material> material_;
    std::optional<PbrEnvironment> pbrEnv_;
  }

